const outcomes = [];
for (let a = 1; a <= 6; a++) {
  for (let b = 1; b <= 6; b++) outcomes.push([a, b]);
}
const hits = outcomes.filter(([a, b]) => Math.max(a, b) >= 5).length;
const gcd = (x, y) => (y === 0 ? x : gcd(y, x % y));
const g = gcd(hits, outcomes.length);
return hits / g + outcomes.length / g;
